 if(!is_resource($p))return ['ok'=>false,'message'=>'Serviço indisponível.'];
 fwrite($pipes[0],json_encode($data));fclose($pipes[0]);$out=stream_get_contents($pipes[1]);fclose($pipes[1]);fclose($pipes[2]);proc_close($p);
